import java.util.*;

class Solution {
  public int finalPositionOfSnake(int n, List<String> commands) {
    int r = 0, c = 0;
    for (String command : commands) {
      if (command.equals("UP")) r--;
      else if (command.equals("DOWN")) r++;
      else if (command.equals("LEFT")) c--;
      else c++;
    }
    return r * n + c;
  }
}
